import{c as a,Q as n,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"InitBufPool","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitBufPool","slug":"initbufpool"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBufPool.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBufPool.md"}'),l={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBufPool.md"};function o(p,t,i,r,d,u){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="initbufpool" tabindex="-1">InitBufPool <a class="header-anchor" href="#initbufpool" aria-label="Permalink to &quot;InitBufPool&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>初始化TBufPool内存资源池。本接口适用于内存资源有限时，希望手动指定UB/L1内存资源复用的场景。本接口初始化后在整体内存资源中划分出一块子资源池。划分出的子资源池TBufPool，提供了如下方式进行资源管理：</p><ul><li>TPipe::InitBufPool的重载接口指定与其他TBufPool子资源池复用;</li><li>TBufPool::<a href="./../TBufPool/InitBufPool-55.html">InitBufPool</a>接口对子资源池继续划分；</li><li>TBufPool::<a href="./../TBufPool/InitBuffer-56.html">InitBuffer</a>接口分配Buffer；</li></ul><p>关于TBufPool的具体介绍及资源划分图示请参考<a href="./../TBufPool/TBufPool.html">TBufPool</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBufPool(T&amp; bufPool, uint32_t len)</span></span>
<span class="line"><span>template &lt;class T, class U&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBufPool(T&amp; bufPool, uint32_t len, U&amp; shareBuf)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>bufPool的类型。</td></tr><tr><td>U</td><td>shareBuf的类型。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>bufPool</td><td>输入</td><td>新划分的资源池，类型为TBufPool。</td></tr><tr><td>len</td><td>输入</td><td>新划分资源池长度，单位为Byte，非32Bytes对齐会自动补齐至32Bytes对齐。</td></tr><tr><td>shareBuf</td><td>输入</td><td>被复用资源池，类型为TBufPool，新划分资源池与被复用资源池共享起始地址及长度。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>新划分的资源池与被复用资源池的硬件属性需要一致，两者共享起始地址及长度；</li><li>输入长度需要小于等于被复用资源池长度；</li><li>其他泛用约束参考<a href="./../TBufPool/TBufPool.html">TBufPool</a>。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>由于物理内存的大小有限，在计算过程没有数据依赖的场景或数据依赖串行的场景下，可以通过指定内存复用解决资源不足的问题。完整算子样例参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/04_resource_management/tbufpool_management" target="_blank" rel="noreferrer">tbufpool_management样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 声明一个指向TPipe管道对象的指针</span></span>
<span class="line"><span>AscendC::TPipe* pipe;</span></span>
<span class="line"><span>// 定义两个子资源池对象tbufPool1和tbufPool2</span></span>
<span class="line"><span>AscendC::TBufPool&lt;AscendC::TPosition::VECCALC&gt; tbufPool1, tbufPool2;</span></span>
<span class="line"><span>// 初始化第一个子资源池tbufPool1</span></span>
<span class="line"><span>pipe-&gt;InitBufPool(tbufPool1, bufSize * 3);</span></span>
<span class="line"><span>// 初始化第二个子资源池tbufPool2，并指定tbufPool2复用tbufPool1的起始地址及长度；</span></span>
<span class="line"><span>pipe-&gt;InitBufPool(tbufPool2, bufSize * 3, tbufPool1);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 计算串行，不存在数据踩踏，实现了内存复用及自动同步的能力</span></span>
<span class="line"><span>tbufPool1.InitBuffer(srcQue0, 1, bufSize);</span></span>
<span class="line"><span>tbufPool1.InitBuffer(srcQue1, 1, bufSize);</span></span>
<span class="line"><span>tbufPool1.InitBuffer(dstQue0, 1, bufSize);</span></span>
<span class="line"><span>CopyIn();</span></span>
<span class="line"><span>Compute(); </span></span>
<span class="line"><span>CopyOut();</span></span>
<span class="line"><span>tbufPool1.Reset();</span></span>
<span class="line"><span>tbufPool2.InitBuffer(srcQue2, 1, bufSize);</span></span>
<span class="line"><span>tbufPool2.InitBuffer(srcQue3, 1, bufSize);</span></span>
<span class="line"><span>tbufPool2.InitBuffer(dstQue1, 1, bufSize);</span></span>
<span class="line"><span>CopyIn1();</span></span>
<span class="line"><span>Compute1();</span></span>
<span class="line"><span>CopyOut1();</span></span>
<span class="line"><span>tbufPool2.Reset();</span></span></code></pre></div>`,21)])])}const h=a(l,[["render",o]]);export{c as __pageData,h as default};
